const acorn=require('acorn');
const {JSDOM,VirtualConsole}=require('jsdom');

const repo=process.env.GH_REPOSITORY,token=process.env.GH_TOKEN,path='siza-mobile-test/index.html';
const headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'};
const api=`https://api.github.com/repos/${repo}/contents/${path}`;
const assert=(v,m)=>{if(!v)throw new Error(m)};
async function getFile(p){const r=await fetch(`https://api.github.com/repos/${repo}/contents/${p}?ref=main`,{headers});if(!r.ok)throw new Error(`${p}: GET ${r.status}`);const f=await r.json();return{sha:f.sha,text:Buffer.from(f.content.replace(/\n/g,''),'base64').toString('utf8')}}
function parse(html){const so=html.lastIndexOf('<script>'),sc=html.indexOf('</script>',so);assert(so>=0&&sc>so,'main script not found');const start=so+8,code=html.slice(start,sc),ast=acorn.parse(code,{ecmaVersion:'latest'}),decl=[];function walk(n){if(!n||typeof n!=='object')return;if(n.type==='FunctionDeclaration'&&n.id)decl.push(n);for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return{start,sc,code,decl}}
function inlineCore(html,files){let out=html;for(const[name,text]of [['card-effects.js',files.effects],['card-schema.js',files.schema],['cards.js',files.cards],['card-renderer.js',files.renderer]]){const tag=`<script src="../siza-core/${name}"></script>`;assert(out.includes(tag),`Missing core tag ${name}`);out=out.replace(tag,`<script>${text}</script>`)}return out}
function makeDom(html,label){const vc=new VirtualConsole();vc.on('jsdomError',e=>console.error(`[JSDOM ${label}]`,e.message));return new JSDOM(html,{runScripts:'dangerously',url:'https://siza.local/siza-mobile-test/',virtualConsole:vc})}
function report(html){const p=parse(html),m=new Map();for(const n of p.decl)m.set(n.id.name,(m.get(n.id.name)||0)+1);return{total:p.decl.length,dupes:[...m.entries()].filter(([,c])=>c>1)}}
function cleanup(html){const p=parse(html),spec={passResponse:2,responseWindowHtml:2},cuts=[];for(const[name,expected]of Object.entries(spec)){const nodes=p.decl.filter(n=>n.id.name===name).sort((a,b)=>a.start-b.start);assert(nodes.length===expected,`${name}: expected ${expected}, got ${nodes.length}`);cuts.push([nodes[0].start,nodes[0].end,name])}let code=p.code;for(const[start,end,name]of cuts.sort((a,b)=>b[0]-a[0]))code=code.slice(0,start)+`/* canonicalized ${name}: earlier declaration removed */`+code.slice(end);return html.slice(0,p.start)+code+html.slice(p.sc)}

(async()=>{
 const index=await getFile(path),files={effects:(await getFile('siza-core/card-effects.js')).text,schema:(await getFile('siza-core/card-schema.js')).text,cards:(await getFile('siza-core/cards.js')).text,renderer:(await getFile('siza-core/card-renderer.js')).text};console.log('Current Mobile blob '+index.sha);
 const before=report(index.text);assert(before.dupes.some(([n,c])=>n==='passResponse'&&c===2),'passResponse precondition failed');assert(before.dupes.some(([n,c])=>n==='responseWindowHtml'&&c===2),'responseWindowHtml precondition failed');
 const html=cleanup(index.text),after=report(html);assert(!after.dupes.some(([n])=>n==='passResponse'||n==='responseWindowHtml'),'Priority duplicates remain');assert(after.total===before.total-2,`Expected 2 declarations removed, got ${before.total-after.total}`);assert(after.dupes.length===before.dupes.length-2,`Expected ${before.dupes.length-2} duplicate names, got ${after.dupes.length}`);console.log(`Duplicate names ${before.dupes.length} -> ${after.dupes.length}; declarations ${before.total} -> ${after.total}`);
 const marker='window.SIZA={',probe=`window.__PRIORITY_TEST__={createMatch,setMatch:m=>state.match=m,getMatch:()=>state.match,responseWindowHtml,passResponse};\n`;assert(index.text.includes(marker)&&html.includes(marker),'SIZA marker missing');
 const oldDom=makeDom(inlineCore(index.text,files).replace(marker,probe+marker),'old'),newDom=makeDom(inlineCore(html,files).replace(marker,probe+marker),'new');oldDom.window.setTimeout=()=>0;newDom.window.setTimeout=()=>0;
 function snap(dom){const H=dom.window.__PRIORITY_TEST__,M=H.createMatch(false,'prepare');H.setMatch(M);M.stack=[{id:'target',cardId:'spark',owner:'enemy'}];M.responseWindow={stackId:'target',responder:'player'};M.active='response';M.phase='Tu prioridad';const ui=H.responseWindowHtml();H.passResponse();return{ui,window:M.responseWindow,pending:M.pendingResolution,active:M.active,phase:M.phase,stack:M.stack.map(x=>x.cardId)}}
 const a=snap(oldDom),b=snap(newDom);assert(JSON.stringify(a)===JSON.stringify(b),'Priority behavior changed');assert(a.ui.includes('TU RESPUESTA')&&a.ui.includes('PASAR PRIORIDAD')&&a.window===null&&a.pending===true&&a.active==='resolving'&&a.phase==='Stack listo'&&a.stack.length===1,'Canonical priority contract unexpected');console.log('PASS priority window and pass semantics unchanged');
 const ao=oldDom.window.SIZA.runArenaCriticalV071(),an=newDom.window.SIZA.runArenaCriticalV071();assert(ao.passed===ao.total&&an.passed===an.total,'Arena critical regression');console.log(`PASS Arena old ${ao.passed}/${ao.total} -> new ${an.passed}/${an.total}`);oldDom.window.close();newDom.window.close();
 const w=await fetch(api,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({message:'Canonicalize priority and response declarations',content:Buffer.from(html,'utf8').toString('base64'),sha:index.sha,branch:'main'})});if(!w.ok)throw new Error(`PUT ${w.status}: ${await w.text()}`);const out=await w.json();console.log('COMMIT '+out.commit.sha);
})().catch(e=>{console.error(e.stack||e.message);process.exit(1)});
